package in.orbitai.mobile;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.zip.*;import javax.crypto.*;import javax.crypto.spec.*;
/** Portable encrypted snapshot; API keys and computer credentials are never packed. */
final class Sync {
 static byte[] decode(String value){return android.util.Base64.decode(value,android.util.Base64.NO_WRAP);}
 static String encode(byte[] value){return android.util.Base64.encodeToString(value,android.util.Base64.NO_WRAP);}
 static javax.crypto.SecretKey key(String phrase,byte[] salt)throws Exception{if(phrase.length()<12||phrase.length()>200)throw new IOException("Use a backup passphrase of 12–200 characters");PBEKeySpec spec=new PBEKeySpec(phrase.toCharArray(),salt,600000,256);try{return new SecretKeySpec(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded(),"AES");}finally{spec.clearPassword();}}
 static JSONObject pack(Context c,String state,String phrase)throws Exception{JSONObject root=new JSONObject().put("state",new JSONObject(state));JSONArray workspaces=new JSONArray(),bots=root.getJSONObject("state").getJSONArray("bots");int size=state.length();if(bots.length()>100)throw new IOException("Backup supports up to 100 bots");for(int i=0;i<bots.length();i++){String id=Store.safe(bots.getJSONObject(i).getString("id"));JSONObject files=new JSONObject();JSONArray names=Store.files(c,id);for(int j=0;j<names.length();j++){String name=names.getString(j),text=Store.read(c,id,name);size+=text.length();if(size>12000000)throw new IOException("Backup limit: 12 million characters");files.put(name,text);}workspaces.put(new JSONObject().put("id",id).put("files",files).put("memory",Store.get(c,"memory:"+id,"")));}root.put("workspaces",workspaces);ByteArrayOutputStream compressed=new ByteArrayOutputStream();try(GZIPOutputStream out=new GZIPOutputStream(compressed)){out.write(root.toString().getBytes(StandardCharsets.UTF_8));}byte[] salt=new byte[16],iv=new byte[12];SecureRandom random=new SecureRandom();random.nextBytes(salt);random.nextBytes(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key(phrase,salt),new GCMParameterSpec(128,iv));return new JSONObject().put("version",1).put("salt",encode(salt)).put("iv",encode(iv)).put("data",encode(cipher.doFinal(compressed.toByteArray())));}
 static JSONObject unpack(JSONObject envelope,String phrase)throws Exception{byte[] salt=decode(envelope.getString("salt")),iv=decode(envelope.getString("iv"));if(envelope.getInt("version")!=1||salt.length!=16||iv.length!=12)throw new IOException("Unsupported backup envelope");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(phrase,salt),new GCMParameterSpec(128,iv));byte[] clear=cipher.doFinal(decode(envelope.getString("data")));ByteArrayOutputStream out=new ByteArrayOutputStream();try(GZIPInputStream in=new GZIPInputStream(new ByteArrayInputStream(clear))){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>48000000)throw new IOException("Decompressed backup too large");}}return new JSONObject(out.toString("UTF-8"));}
 static JSONObject sanitize(JSONObject backup)throws Exception{JSONObject state=backup.getJSONObject("state"),settings=state.getJSONObject("settings");JSONArray bots=state.getJSONArray("bots");if(bots.length()>100)throw new IOException("Too many bots");for(int i=0;i<bots.length();i++){JSONObject bot=bots.getJSONObject(i);Store.safe(bot.getString("id"));bot.getString("name");bot.getJSONArray("messages");JSONArray tasks=bot.getJSONArray("tasks");for(int j=0;j<tasks.length();j++){JSONObject t=tasks.getJSONObject(j);if(t.optString("status").matches("queued|running|stopping"))t.put("status","interrupted").put("error","Restored snapshot; inspect partial work before retrying");}}JSONArray routines=state.optJSONArray("routines");if(routines!=null)for(int i=0;i<routines.length();i++)routines.getJSONObject(i).put("enabled",false);for(String permission:new String[]{"desktop","semantic","serverMail","crawl","web","xsearch","code"})settings.put(permission,false);if(state.toString().length()>8000000)throw new IOException("Restored state exceeds app limit");JSONArray spaces=backup.getJSONArray("workspaces");java.util.Set<String> ids=new java.util.HashSet<>();for(int i=0;i<spaces.length();i++){JSONObject ws=spaces.getJSONObject(i);Store.safe(ws.getString("id"));if(!ids.add(ws.getString("id")))throw new IOException("Duplicate workspace");JSONObject files=ws.getJSONObject("files");if(files.length()>30)throw new IOException("Too many files");java.util.Iterator<String> names=files.keys();while(names.hasNext()){String name=names.next();Store.safe(name);if(files.getString(name).length()>300000)throw new IOException("File too large");}if(ws.optString("memory").length()>16000)throw new IOException("Memory too large");}return state;}
 static void restore(Context c,JSONObject backup)throws Exception{
  JSONObject state=sanitize(backup);JSONArray spaces=backup.getJSONArray("workspaces");java.util.List<String[]> plan=new java.util.ArrayList<>();String oldState=Store.get(c,"state","{}");boolean committed=false;
  try{
   // Stage every encrypted file first, leaving existing workspaces untouched.
   for(int i=0;i<spaces.length();i++){JSONObject ws=spaces.getJSONObject(i);String id=ws.getString("id"),stage="restore_"+java.util.UUID.randomUUID().toString().replace("-","");String old="prior_"+java.util.UUID.randomUUID().toString().replace("-","");String[] item=new String[]{id,stage,old,Store.get(c,"memory:"+id,""),"0"};plan.add(item);Store.folder(c,stage);JSONObject files=ws.getJSONObject("files");java.util.Iterator<String> names=files.keys();while(names.hasNext()){String name=names.next();Store.artifact(c,stage,name,files.getString(name));}}
   for(int i=0;i<plan.size();i++){String[] item=plan.get(i);File target=Store.folder(c,item[0]),stage=Store.folder(c,item[1]),old=new File(target.getParentFile(),item[2]);if(!target.renameTo(old))throw new IOException("Cannot stage prior workspace");if(!stage.renameTo(target)){old.renameTo(target);throw new IOException("Cannot activate restored workspace");}item[4]="1";Store.put(c,"memory:"+item[0],spaces.getJSONObject(i).optString("memory"));}
   Store.put(c,"state",state.toString());committed=true;
  }finally{
   if(!committed){for(String[] item:plan)if(item[4].equals("1")){Store.wipe(c,item[0]);File parent=Store.folder(c,item[0]).getParentFile();new File(parent,item[0]).delete();new File(parent,item[2]).renameTo(new File(parent,item[0]));try{Store.put(c,"memory:"+item[0],item[3]);}catch(Exception ignored){}}try{Store.put(c,"state",oldState);}catch(Exception ignored){}}
   for(String[] item:plan){Store.wipe(c,item[1]);if(committed)Store.wipe(c,item[2]);}
  }
 }
}
